INSERT INTO `love_inspiration` VALUES (1, 1, NULL, '我今天真的很想你，比昨天多一点，比明天少一点。', '甜宠', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (2, 1, NULL, '全世界那么多人，为什么偏偏遇见你——因为你是我的例外。', '甜宠', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (3, 1, NULL, '你一笑，我就沦陷了，这题对我来说超纲了。', '甜宠', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (4, 1, NULL, '别人问我最近过得怎么样，我说挺好的，因为有你。', '甜宠', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (5, 1, NULL, '我想把世界上最好的都给你，后来发现世界上最好的就是你。', '甜宠', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (6, 1, NULL, '你是我温暖的手套，冰镇的啤酒，带着阳光味道的衬衫。', '甜宠', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (7, 1, NULL, '我的偏爱有限，全部留给你刚好用完。', '甜宠', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (8, 1, NULL, '遇见你之后，我的口头禅从「随便」变成了「听你的」。', '甜宠', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (9, 1, NULL, '今天也要提醒你：有人在偷偷喜欢你，就是我。', '日常', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (10, 1, NULL, '一日三餐，四季冷暖，都想和你一起过。', '日常', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (11, 1, NULL, '买菜做饭洗碗的时候，就觉得日子因为有你在发光。', '日常', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (12, 1, NULL, '不用刻意纪念，和你在一起的每一天都值得记下来。', '日常', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (13, 1, NULL, '下班回家的路上想好了今晚吃什么，最后还是决定：想你。', '日常', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (14, 1, NULL, '今天也没发生什么大事，就是又喜欢你了一整天。', '日常', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (15, 1, NULL, '你在闹，我在笑，这就是我想要的生活。', '日常', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (16, 1, NULL, '天气预报说今天有雨，我带了两把伞，一把给你。', '日常', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (17, 1, NULL, '我喜欢你，不是一时兴起，而是蓄谋已久。', '表白', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (18, 1, NULL, '我见过很多风景，但都不及你朝我走来的样子。', '表白', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (19, 1, NULL, '余生请多指教，我打算赖上你了。', '表白', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (20, 1, NULL, '情话是我学不会的套路，但喜欢你是我的天赋。', '表白', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (21, 1, NULL, '你不用多好，我喜欢就好；我没有多好，你不嫌弃就好。', '表白', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (22, 1, NULL, '山野万里，你是我藏在星星里的浪漫。', '表白', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (23, 1, NULL, '我最近手头有点紧，想借你的手牵一牵。', '表白', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (24, 1, NULL, '从遇见你开始，我的人生就只有两种状态：想你，和见你。', '表白', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (25, 2, '一起下厨做一顿饭', '挑一道都想吃的菜，分工一个掌勺一个打下手，摆盘拍照记录成果。', '室内', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (26, 2, '拼图 / 积木挑战', '选一幅 500 片以上的拼图或一套积木，一下午的专注时光，完成后装裱留念。', '室内', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (27, 2, '双人桌游之夜', '翻翻家里落灰的桌游，或去桌游吧玩几局双人对战，输的人负责倒水。', '室内', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (28, 2, '居家电影马拉松', '选一个系列连看两三部，配上爆米花和小零食，窝在沙发里一整天。', '室内', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (29, 2, 'DIY 陶艺体验', '找一家陶艺工作室，亲手做一个杯子或小摆件，交换成品当纪念。', '室内', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (30, 2, '城市漫游 City Walk', '挑一条没走过的老街区，慢慢走慢慢拍，遇见好看的小店就进去逛逛。', '户外', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (31, 2, '公园野餐日', '带上野餐垫、水果和小音箱，找一片树荫躺一下午，看云发呆。', '户外', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (32, 2, '骑行探店', '租两辆共享单车，沿着河或绿道骑到郊外的咖啡馆，累并快乐着。', '户外', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (33, 2, '看一场日出或日落', '早起去山顶或江边看日出，或者傍晚找视野好的天台看日落，拍下剪影合影。', '户外', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (34, 2, '夜市扫街', '从街头吃到街尾，每人负责选三样，互相投喂打分，评选本日最佳。', '美食', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (35, 2, '火锅 + 双人纪录片', '晚上吃热气腾腾的火锅，回家路上挑一部美食纪录片，边吃边聊。', '美食', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (36, 2, '烘焙半成品日', '去 DIY 烘焙坊做饼干或蛋糕，失败也无所谓，糊了的也是限量款。', '美食', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (37, 2, '便利店晚餐企划', '每人 30 元预算在便利店凑一顿晚餐，坐在窗边吃，给每种食物打分。', '美食', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (38, 2, '私人影院双人厅', '订一间双人点播影院，自己挑片，瘫着看完一部想看很久的电影。', '观影', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (39, 2, '老片重映打卡', '关注本地影院的重映排片，在大银幕重温一部经典，感受岁月的味道。', '观影', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (40, 2, '各选一部互赌评分', '每人各选一部对方没看过的片子，看完互打分，输的人请下一顿。', '观影', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (41, 2, '露天电影 / 音乐节', '关注本地露天放映或小型音乐节活动，带上小毯子去现场，氛围感拉满。', '观影', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (42, 2, '手写交换日记', '买一本好看的笔记本，轮流每周写一篇给对方看，写满一年再回头翻。', '手作', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (43, 2, '纪念相册整理夜', '把手机里的合影挑出来打印，做成一本实体相册，标注日期和当时的故事。', '手作', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (44, 2, '情侣手链 DIY', '去手作店编两条手链或串珠，各戴一条，出门就是显眼包情侣。', '手作', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (45, 2, '给对方做一件小礼物', '折纸、绘画、粘土不限，本周内偷偷准备，周末交换揭晓。', '手作', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (46, 2, '逛一场博物馆 / 展览', '挑一个双方都感兴趣的展，租两台讲解器，逛完在文创店挑一枚冰箱贴。', '户外', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (47, 2, '早午餐 Brunch 之约', '周末睡到自然醒，找一家评价好的 Brunch 店，慢悠悠吃到中午，顺便散步消食。', '美食', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
INSERT INTO `love_inspiration` VALUES (48, 2, '新片首日场', '盯一部两人都想看的上映新片，买首日场 or 首周末场，看完趁热打铁聊剧情。', '观影', 0, '1', '2026-10-19 18:23:25', '1', '2026-10-19 18:23:25', b'0');
